L31: function maskCommentsAndTemplates(source) {

'use strict';

const fs = require('fs');
const path = require('path');

const pc = require('./persona-config');

const profilesDir = path.resolve(__dirname, '..', 'profiles');

function listProfileNames() {
  try {
    if (!fs.existsSync(profilesDir)) return [];
    return fs.readdirSync(profilesDir)
      .filter((f) => f.endsWith('.md'))
      .map((f) => f.slice(0, -3));
  } catch (e) {
    return [];
  }
}

function checkPersonaConfig(cwd) {
  const p = pc.configPath(cwd);
  const base = {
    status: 'missing',
    path: p,
    entries: 0,
    unknownPersonas: [],
    unsupportedHarnesses: [],
  };

  if (!fs.existsSync(p)) {
    return base;
  }

  let data;
  try {
    data = pc.readConfig(cwd);
  } catch (e) {
    if (e instanceof pc.ConfigError) {
      return Object.assign({}, base, { status: 'error', message: e.message });
    }
    throw e;
  }

  const personas = (data && data.personas) || {};
  const entries = Object.keys(personas).length;
  const known = new Set(listProfileNames());
  const unknownPersonas = Object.keys(personas).filter((name) => !known.has(name));

  const unsupportedHarnesses = [];
  for (const [name, entry] of Object.entries(personas)) {
    if (entry && typeof entry === 'object' && !Array.isArray(entry) &&
        typeof entry.harness === 'string' && entry.harness.trim() !== '' &&
        !pc.SUPPORTED_DISPATCH_HARNESSES.includes(entry.harness)) {
      unsupportedHarnesses.push({ persona: name, harness: entry.harness });
    }
  }

  return {
    status: 'ok',
    path: p,
    entries: entries,
    unknownPersonas: unknownPersonas,
    unsupportedHarnesses: unsupportedHarnesses,
  };
}

function parseModsList(output) {
  const text = String(output == null ? '' : output);
  const lines = text.split(/\r?\n/);
  // Find lines referencing righthand
  const relevant = lines.filter((l) => /righthand/i.test(l));
  const installed = relevant.length > 0;

  let version = null;
  const searchLines = relevant.length > 0 ? relevant : lines;
  for (const line of searchLines) {
    const m = line.match(/v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/);
    if (m) {
      version = m[1];
      break;
    }
  }
  // If no version found in relevant lines but installed, try whole output
  if (installed && version === null) {
    const m = text.match(/righthand[^\n]*?v?(\d+\.\d+\.\d+(?:-[\w.]+)?)/i);
    if (m) version = m[1];
  }

  return { installed: installed, version: version };
}

function parsePiList(output) {
  const text = String(output == null ? '' : output);
  const lines = text.split(/\r?\n/);
  const packages = [];
  for (let i = 0; i < lines.length; i++) {
    const idMatch = lines[i].match(/^\s+(npm:\S+)(?:\s+v?(\d+\.\d+\.\d+(?:-[\w.]+)?))?\s*$/i);
    if (!idMatch) continue;
    const packageMatch = idMatch[1].match(/^npm:(@agirahman\/righthand)(?:@v?(\d+\.\d+\.\d+(?:-[\w.]+)?))?$/i);
    if (!packageMatch) continue;
    const installPath = (lines[i + 1] || '').trim();
    packages.push({
      id: `npm:${packageMatch[1]}`,
      version: idMatch[2] || packageMatch[2] || null,
      path: installPath || null,
    });
  }
  return packages;
}

function parseVersion(v) {
  if (typeof v !== 'string') return null;
  const m = v.trim().match(/^v?(\d+)\.(\d+)\.(\d+)/);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3])];
}

function compareVersions(installed, expected) {
  const a = parseVersion(installed);
  const b = parseVersion(expected);
  if (!a || !b) return 'unknown';
  if (a[0] === b[0] && a[1] === b[1] && a[2] === b[2]) return 'match';
  return 'drift';
}

function versionDrift(entry, label, requiresParsed) {
  if (!entry.version || !entry.expected) return [];
  if (!entry.installed) return [];
  if (requiresParsed && !entry.parsed) return [];
  if (compareVersions(entry.version, entry.expected) !== 'drift') return [];
  return [`${label} version drift: ${entry.version} vs ${entry.expected}`];
}

function collectStrictFailures(input) {
  input = input || {};
  const failures = [];
  const pc = input.personaConfig || {};
  if (pc.status === 'error') {
    failures.push(pc.message || 'persona config error');
  }
  // unsupported harness detection: if pc has unsupportedHarnesses
  if (Array.isArray(pc.unsupportedHarnesses) && pc.unsupportedHarnesses.length > 0) {
    for (const h of pc.unsupportedHarnesses) {
      failures.push(`unsupported harness: ${h.persona} ${h.harness}`);
    }
  }
  const skills = input.skills || {};
  const missing = Array.isArray(skills.missingOrStale) ? skills.missingOrStale : [];
  if (missing.length > 0) {
    failures.push(`capability skills missing or stale: ${missing.join(', ')}`);
  }
  if (Array.isArray(input.harnesses)) {
    for (const h of input.harnesses) {
      if (!h || !h.data) continue;
      failures.push(...versionDrift(h.data, h.label || 'mod', !!h.requiresParsed));
    }
  } else {
    // Legacy shape: mod/pi keys supplied directly.
    if (input.mod) failures.push(...versionDrift(input.mod, 'mod', true));
    if (input.pi) failures.push(...versionDrift(input.pi, 'pi package', false));
  }
  return failures;
}

module.exports = {
  checkPersonaConfig: checkPersonaConfig,
  parseModsList: parseModsList,
  parsePiList: parsePiList,
  compareVersions: compareVersions,
  collectStrictFailures: collectStrictFailures,
};

'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');

const registry = require('../harness/registry');
const { isInPath } = require('../harness/lib/path');

const root = path.resolve(__dirname, '..');
const skillsDir = path.join(root, 'skills');

const HARNESSES = registry.HARNESSES;

function resolveHarness(name) {
  return registry.resolveHarness(name);
}

function configBaseDir() {
  const env = process.env.XDG_CONFIG_HOME;
  if (env && path.isAbsolute(env)) return env;
  return path.join(os.homedir(), '.config');
}

function resolveDestBase(h) {
  if (h && h.destBase === 'home') return configBaseDir();
  return process.cwd();
}

function resolveDestPath(h, dest) {
  return path.join(resolveDestBase(h), dest);
}

function listSkillNames() {
  if (!fs.existsSync(skillsDir)) return [];
  return fs.readdirSync(skillsDir)
    .filter((f) => !f.startsWith('.') && (() => {
      try { return fs.statSync(path.join(skillsDir, f)).isDirectory(); } catch (e) { return false; }
    })())
    .sort();
}

function skillsOwnerManifest() {
  const m = registry.skillsOwner();
  if (!m || typeof m.skillsTarget !== 'function') {
    throw new Error('no harness manifest declares a skillsTarget hook');
  }
  return m;
}

function resolveSkillTarget(harness, opts) {
  opts = opts || {};
  // Preserve historical behaviour: ignores the harness argument and always
  // resolves the skills-owning manifest's target.
  return skillsOwnerManifest().skillsTarget(opts);
}

function walkFiles(dir, base) {
  base = base || dir;
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      out.push(...walkFiles(full, base));
    } else if (entry.isFile()) {
      out.push(path.relative(base, full));
    }
  }
  return out;
}

function readSafe(p) {
  try { return fs.readFileSync(p); } catch (e) { return null; }
}

function syncSkills(harness, opts) {
  opts = opts || {};
  const key = typeof harness === 'string' ? resolveHarness(harness) : harness;
  const canonical = (typeof key === 'string' && HARNESSES[key]) ? key : (typeof harness === 'string' ? String(harness).toLowerCase() : null);
  const m = canonical ? registry.getManifest(canonical) : null;
  // Only harnesses declaring a skillsTarget sync.
  if (!m || typeof m.skillsTarget !== 'function') {
    return { written: 0, unchanged: 0, files: [] };
  }
  const dryRun = !!opts.dryRun;
  const targetRoot = m.skillsTarget(opts);
  const names = listSkillNames();
  let written = 0;
  let unchanged = 0;
  const files = [];
  const failed = [];
  const skills = {};

  for (const name of names) {
    const srcRoot = path.join(skillsDir, name);
    const destRoot = path.join(targetRoot, name);
    const relFiles = walkFiles(srcRoot, srcRoot);
    const skillStats = { written: 0, unchanged: 0, failed: 0, files: [] };
    for (const rel of relFiles) {
      const srcFile = path.join(srcRoot, rel);
      const destFile = path.join(destRoot, rel);
      let srcBuf;
      try { srcBuf = fs.readFileSync(srcFile); } catch (e) { continue; }
      const destBuf = readSafe(destFile);
      const identical = destBuf !== null && Buffer.compare(srcBuf, destBuf) === 0;
      const prefixed = name + '/' + rel.split(path.sep).join('/');
      files.push(prefixed);
      skillStats.files.push(prefixed);
      if (identical) {
        unchanged++;
        skillStats.unchanged++;
        continue;
      }
      if (dryRun) {
        written++;
        skillStats.written++;
        continue;
      }
      try {
        fs.mkdirSync(path.dirname(destFile), { recursive: true });
        fs.writeFileSync(destFile, srcBuf);
        written++;
        skillStats.written++;
      } catch (e) {
        failed.push(prefixed);
        skillStats.failed++;
      }
    }
    skills[name] = skillStats;
  }
  return { written, unchanged, files, failed, skills };
}

function checkSkills(opts) {
  opts = opts || {};
  // Check the skills-owning manifest's target (reported by doctor today).
  const targetRoot = resolveSkillTarget(null, opts);
  const names = listSkillNames();
  const missingOrStale = [];
  let installed = 0;
  for (const name of names) {
    const srcRoot = path.join(skillsDir, name);
    const destRoot = path.join(targetRoot, name);
    const relFiles = walkFiles(srcRoot, srcRoot);
    let ok = relFiles.length > 0;
    for (const rel of relFiles) {
      const srcBuf = readSafe(path.join(srcRoot, rel));
      const destBuf = readSafe(path.join(destRoot, rel));
      if (srcBuf === null || destBuf === null || Buffer.compare(srcBuf, destBuf) !== 0) {
        ok = false;
        break;
      }
    }
    if (ok) installed++;
    else missingOrStale.push(name);
  }
  return { installed, total: names.length, missingOrStale };
}

module.exports = {
  HARNESSES,
  resolveHarness,
  resolveDestBase,
  resolveDestPath,
  isInPath,
  skillsDir,
  root,
  listSkillNames,
  syncSkills,
  checkSkills,
  resolveSkillTarget,
};

'use strict';

const cmdcLaunch = require('../harness/cmdc/launch');

module.exports = {
  CMDC_BIN: cmdcLaunch.CMDC_BIN,
  buildLaunchArgs: cmdcLaunch.buildLaunchArgs,
  formatCommand: cmdcLaunch.formatCommand,
};

'use strict';

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const registry = require('../harness/registry');

const CONFIG_REL = '.righthand/persona.json';
const SUPPORTED_DISPATCH_HARNESSES = registry.dispatchable();

class ConfigError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ConfigError';
  }
}

function configPath(cwd = process.cwd()) {
  return path.join(cwd, CONFIG_REL);
}

function validateConfig(input, file) {
  let data = input;
  let fileLabel = file;
  if (typeof input === 'string') {
    if (fs.existsSync(input)) {
      fileLabel = fileLabel || input;
      try {
        data = fs.readFileSync(input, 'utf8');
      } catch (e) {
        throw new ConfigError(`Unable to read ${fileLabel || input} (${CONFIG_REL}): ${e.message}`);
      }
    }
    if (typeof data === 'string') {
      try {
        data = JSON.parse(data);
      } catch (e) {
        throw new ConfigError(`invalid JSON in ${fileLabel || CONFIG_REL}: ${e.message}`);
      }
    }
  }
  if (!fileLabel) fileLabel = CONFIG_REL;
  const displayLabel = String(fileLabel).includes('/') ? fileLabel : `${fileLabel} (${CONFIG_REL})`;

  if (typeof data !== 'object' || data === null || Array.isArray(data)) {
    throw new ConfigError(`${displayLabel}: root must be a JSON object`);
  }

  for (const key of Object.keys(data)) {
    if (key !== 'personas') {
      throw new ConfigError(`${displayLabel}: unknown top-level key "${key}"`);
    }
  }

  if (Object.prototype.hasOwnProperty.call(data, 'personas')) {
    const personas = data.personas;
    if (typeof personas !== 'object' || personas === null || Array.isArray(personas)) {
      throw new ConfigError(`${displayLabel}: "personas" must be an object`);
    }
    for (const [name, entry] of Object.entries(personas)) {
      if (typeof entry !== 'object' || entry === null || Array.isArray(entry)) {
        throw new ConfigError(`${displayLabel}: persona "${name}" entry must be an object`);
      }
      for (const field of Object.keys(entry)) {
        if (field !== 'model' && field !== 'harness' && field !== 'models') {
          throw new ConfigError(`${displayLabel}: unknown field "${field}" in persona "${name}"`);
        }
      }
      if (Object.prototype.hasOwnProperty.call(entry, 'model')) {
        const m = entry.model;
        if (typeof m !== 'string' || m.trim() === '') {
          throw new ConfigError(`${displayLabel}: "model" must be a non-empty string for persona "${name}"`);
        }
      }
      if (Object.prototype.hasOwnProperty.call(entry, 'harness')) {
        const h = entry.harness;
        if (typeof h !== 'string' || h.trim() === '') {
          throw new ConfigError(`${displayLabel}: "harness" must be a non-empty string for persona "${name}"`);
        }
        if (!SUPPORTED_DISPATCH_HARNESSES.includes(h)) {
          throw new ConfigError(`${displayLabel}: harness "${h}" for persona "${name}" is not supported for dispatch; supported harnesses: ${SUPPORTED_DISPATCH_HARNESSES.join(', ')}`);
        }
      }
      if (Object.prototype.hasOwnProperty.call(entry, 'models')) {
        const models = entry.models;
        if (typeof models !== 'object' || models === null || Array.isArray(models)) {
          throw new ConfigError(`${displayLabel}: "models" must be an object for persona "${name}"`);
        }
        for (const [target, model] of Object.entries(models)) {
          if (!SUPPORTED_DISPATCH_HARNESSES.includes(target)) {
            throw new ConfigError(`${displayLabel}: models key "${target}" for persona "${name}" is not supported for dispatch; supported harnesses: ${SUPPORTED_DISPATCH_HARNESSES.join(', ')}`);
          }
          if (typeof model !== 'string' || model.trim() === '') {
            throw new ConfigError(`${displayLabel}: models["${target}"] must be a non-empty string for persona "${name}"`);
          }
        }
      }
    }
  }

  return data;
}

function readConfig(cwd = process.cwd()) {
  const p = configPath(cwd);
  if (!fs.existsSync(p)) return {};
  let raw;
  try {
    raw = fs.readFileSync(p, 'utf8');
  } catch (e) {
    throw new ConfigError(`Unable to read ${p} (${CONFIG_REL}): ${e.message}`);
  }
  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    throw new ConfigError(`invalid JSON in ${p} (${CONFIG_REL}): ${e.message}`);
  }
  return validateConfig(data, p);
}

function defaultDispatchOrThrow() {
  const d = registry.defaultDispatchHarness();
  if (!d) throw new Error('no dispatchable harness manifest is installed');
  return d;
}

function orchestratorModel() {
  const paneId = process.env.HERDR_PANE_ID;
  if (!paneId) return null;
  const bin = process.env.HERDR_BIN_PATH || 'herdr';
  let r;
  try {
    r = spawnSync(bin, ['agent', 'list'], { encoding: 'utf8', timeout: 5000 });
  } catch (e) {
    return null;
  }
  if (!r || r.error || r.status !== 0) return null;
  let parsed;
  try {
    parsed = JSON.parse(r.stdout);
  } catch (e) {
    return null;
  }
  const agents = parsed && parsed.result && Array.isArray(parsed.result.agents)
    ? parsed.result.agents
    : null;
  if (!agents) return null;
  const match = agents.find((a) => a && a.pane_id === paneId);
  if (!match) return null;
  const model = match.tokens && typeof match.tokens.model === 'string' ? match.tokens.model : null;
  if (!model || model.trim() === '') return null;
  return model;
}

function resolvePersona(cwd, name, options) {
  options = options || {};
  const config = Object.prototype.hasOwnProperty.call(options, 'config')
    ? (options.config || {})
    : readConfig(cwd);
  const personas = (config && config.personas) || {};
  const entry = Object.prototype.hasOwnProperty.call(personas, name) ? personas[name] : null;

  let harness;
  let harnessSource;
  if (entry && typeof entry.harness === 'string' && entry.harness !== '') {
    harness = entry.harness;
    harnessSource = 'persona';
  } else {
    harness = defaultDispatchOrThrow();
    harnessSource = 'orchestrator';
  }

  const targetHarness = typeof options.targetHarness === 'string' && options.targetHarness !== ''
    ? options.targetHarness
    : null;

  let model;
  let modelSource;
  if (targetHarness && targetHarness !== harness) {
    // Cross-harness launch: a model configured for one harness is not valid
    // for another, so only an explicit per-harness entry is forwarded.
    harness = targetHarness;
    harnessSource = 'argument';
    const models = entry && typeof entry.models === 'object' && entry.models !== null && !Array.isArray(entry.models)
      ? entry.models
      : null;
    const crossModel = models && Object.prototype.hasOwnProperty.call(models, targetHarness)
      ? models[targetHarness]
      : null;
    if (typeof crossModel === 'string' && crossModel.trim() !== '') {
      model = crossModel;
      modelSource = 'persona-models';
    } else {
      model = '';
      modelSource = 'harness-default';
    }
  } else if (entry && typeof entry.model === 'string' && entry.model !== '') {
    model = entry.model;
    modelSource = 'persona';
  } else {
    let om;
    if (Object.prototype.hasOwnProperty.call(options, 'orchestratorModel')) {
      om = options.orchestratorModel;
    } else {
      om = orchestratorModel();
    }
    if (typeof om === 'string' && om.trim() !== '') {
      model = om;
      modelSource = 'orchestrator';
    } else {
      model = '';
      modelSource = 'harness-default';
    }
  }

  const result = {
    persona: name,
    name: name,
    harness: harness,
    harness_source: harnessSource,
    harnessSource: harnessSource,
    model: model,
    model_source: modelSource,
    modelSource: modelSource,
  };
  return result;
}

function formatResolution(...args) {
  let res;
  if (typeof args[0] === 'string') {
    res = resolvePersona(args[0], args[1], args[2] || {});
  } else {
    res = args[0] || {};
  }
  const persona = res.persona || res.name || '';
  const harness = res.harness || '';
  const harnessSource = res.harness_source || res.harnessSource || '';
  const model = res.model == null ? '' : res.model;
  const modelSource = res.model_source || res.modelSource || '';
  return `persona=${persona} harness=${harness} harness_source=${harnessSource} model=${model} model_source=${modelSource}`;
}

module.exports = {
  CONFIG_REL,
  ConfigError,
  SUPPORTED_DISPATCH_HARNESSES,
  configPath,
  readConfig,
  orchestratorModel,
  resolvePersona,
  formatResolution,
  validateConfig,
};

#!/usr/bin/env node
'use strict';

const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');
const { readState, writeState } = require('./state');
const { readConfig, resolvePersona, formatResolution, ConfigError, SUPPORTED_DISPATCH_HARNESSES } = require('./persona-config');
const { formatCommand } = require('./launch');
const pkg = require('../package.json');
const root = path.resolve(__dirname, '..');
const profilesDir = path.join(root, 'profiles');

const harness = require('./harness');
const registry = require('../harness/registry');
const dc = require('./doctor-checks');
const HARNESSES = harness.HARNESSES;
const resolveHarness = harness.resolveHarness;
const resolveDestBase = harness.resolveDestBase;
const resolveDestPath = harness.resolveDestPath;
const isInPath = harness.isInPath;
const skillsDir = harness.skillsDir;
const syncSkills = harness.syncSkills;
const listSkillNames = harness.listSkillNames;
const checkSkills = harness.checkSkills;

const IS_WIN = process.platform === 'win32';

const LAUNCH_USAGE = 'Usage: righthand launch [harness] <persona> [--cwd <dir>] [--print]';

const RETIRED_PERSONAS = ['editor'];

// ---------------------------------------------------------------------------
// Persona helpers
// ---------------------------------------------------------------------------
function listProfiles() {
  if (!fs.existsSync(profilesDir)) return [];
  return fs.readdirSync(profilesDir)
    .filter(f => f.endsWith('.md'))
    .map(f => f.slice(0, -3))
    .sort();
}

function loadProfile(name) {
  const p = path.join(profilesDir, `${name}.md`);
  if (!fs.existsSync(p)) return null;
  return fs.readFileSync(p, 'utf8');
}

// ---------------------------------------------------------------------------
// Harness helpers
// ---------------------------------------------------------------------------
function getHarnessManifest(key) {
  return registry.getManifest(key);
}

function harnessContext() {
  return { dc, pkg, expected: pkg.version, cache: {} };
}

function firstManifestWithHook(hook) {
  for (const m of registry.listManifests()) {
    if (typeof m[hook] === 'function') return m;
  }
  return null;
}

function collectStrictHarnessData(ctx) {
  const out = [];
  for (const m of registry.listManifests()) {
    if (typeof m.strictData !== 'function') continue;
    out.push({
      key: m.key,
      label: m.strictLabel || m.key,
      requiresParsed: !!m.strictRequiresParsed,
      data: m.strictData(ctx),
    });
  }
  return out;
}

function runHarnessSkillsAndProfileCleanup(key, dryRun) {
  const m = getHarnessManifest(key);
  if (!m) return;
  if (typeof m.skillsTarget === 'function') {
    const res = syncSkills(key, { dryRun });
    for (const name of listSkillNames()) {
      const s = (res.skills && res.skills[name]) || { failed: 0 };
      const mark = s.failed > 0 ? '✗' : '✓';
      console.log(`  ${mark} ${name}${dryRun ? ' (dry run)' : ''}`);
      for (const p of (res.failed || []).filter((f) => f.startsWith(name + '/'))) {
        console.log(`    ✗ ${p}`);
      }
    }
    console.log(`  ✓ skills: ${res.written} written, ${res.unchanged} unchanged`);
  }
  if (typeof m.userProfilesDir === 'function') {
    const userProfilesDir = m.userProfilesDir();
    if (fs.existsSync(userProfilesDir)) {
      for (const retired of RETIRED_PERSONAS) {
        const retiredPath = path.join(userProfilesDir, retired + '.md');
        if (fs.existsSync(retiredPath)) {
          if (dryRun) {
            console.log(`  → (dry run) remove retired persona ${retired}`);
          } else {
            try {
              fs.unlinkSync(retiredPath);
              console.log(`  removed retired persona: ${retired}`);
            } catch (e) {
              console.log(`  warning: could not remove ${retiredPath}: ${e && e.message ? e.message : e}`);
            }
          }
        }
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------
function cmdVersion() {
  console.log(`righthand v${pkg.version}`);
}

function cmdInit() {
  const cwd = process.cwd();
  const rhDir = path.join(cwd, '.righthand');
  const dirs = ['.righthand/tickets', '.righthand/skills', '.righthand/state'];

  // Validate .righthand itself
  if (fs.existsSync(rhDir)) {
    const st = fs.statSync(rhDir);
    if (!st.isDirectory()) {
      console.error('Error: .righthand exists and is not a directory');
      process.exit(1);
    }
  }

  for (const rel of dirs) {
    const full = path.join(cwd, rel);
    if (fs.existsSync(full)) {
      const st = fs.statSync(full);
      if (!st.isDirectory()) {
        console.error(`Error: ${rel} exists and is not a directory`);
        process.exit(1);
      }
      console.log(`${rel} exists`);
    } else {
      fs.mkdirSync(full, { recursive: true });
      console.log(`${rel} created`);
    }
  }

  // .gitignore handling
  const giPath = path.join(cwd, '.gitignore');
  const line = '.righthand/';
  let giStatus = 'unchanged';
  if (!fs.existsSync(giPath)) {
    fs.writeFileSync(giPath, line + '\n');
    giStatus = 'updated';
  } else {
    const raw = fs.readFileSync(giPath, 'utf8');
    const lines = raw.split(/\r?\n/);
    const has = lines.some(l => l.trim() === line);
    if (!has) {
      let content = raw;
      if (content.length > 0 && !content.endsWith('\n')) content += '\n';
      content += line + '\n';
      fs.writeFileSync(giPath, content);
      giStatus = 'updated';
    }
  }
  console.log(`.gitignore ${giStatus}`);
}

