function cmdList() {
  const names = listProfiles();
  const state = readState(process.cwd());
  console.log('RightHand personas:');
  for (const n of names) {
    const mark = state.active === n ? ' [ACTIVE]' : '';
    console.log(`  - ${n}${mark}`);
  }
  console.log('\nUsage: righthand switch <name> | righthand off | righthand inject');
}

function cmdSwitch(name) {
  if (!name) {
    console.error('Usage: righthand switch <persona>');
    process.exit(1);
  }
  const names = listProfiles();
  if (!names.includes(name)) {
    console.error(`Unknown persona: ${name}`);
    console.error(`Available: ${names.join(', ')}`);
    process.exit(1);
  }
  writeState({ active: name, updatedAt: new Date().toISOString() }, process.cwd());
  console.log(`Active persona set to: ${name}`);
}

function cmdOff() {
  writeState({ active: null, updatedAt: new Date().toISOString() }, process.cwd());
  console.log('Persona deactivated');
}

function cmdInject() {
  const state = readState(process.cwd());
  if (!state.active) return;
  const raw = loadProfile(state.active);
  if (!raw) return;
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/.exec(raw);
  const body = m ? m[2] : raw;
  console.log(`## Active RightHand persona: ${state.active}\n\n${body.trim()}\n`);
}

function cmdStatus() {
  const cwd = process.cwd();
  const state = readState(cwd);

  if (state.active) {
    console.log(`Active persona : ${state.active}`);
    if (state.updatedAt) console.log(`Last updated   : ${state.updatedAt}`);
  } else {
    console.log('Active persona : none');
    console.log('Run: righthand switch <persona>');
  }

  console.log('Setup harnesses:');
  const ctx = harnessContext();
  for (const [key, h] of Object.entries(HARNESSES)) {
    const m = getHarnessManifest(key);
    let info;
    if (m && typeof m.statusInfo === 'function') {
      info = m.statusInfo(ctx);
    } else if (h.type === 'copy') {
      const allExist = h.files.every(({ dest }) => fs.existsSync(resolveDestPath(h, dest)));
      info = { mark: allExist ? '✓' : '-', text: allExist ? 'set up' : 'not set up' };
    } else {
      const found = h.pathCheck && h.pathCheck.length > 0 && h.pathCheck.some((b) => isInPath(b));
      info = { mark: found ? '✓' : '-', text: found ? 'available' : 'not detected' };
    }
    console.log(`  ${info.mark} ${key}: ${info.text}`);
  }
}

function cmdConfig(personaArg) {
  const cwd = process.cwd();
  const names = listProfiles();
  let config;
  try {
    config = readConfig(cwd);
  } catch (e) {
    if (e instanceof ConfigError) {
      console.error(`Error: ${e.message}`);
      process.exit(2);
    }
    throw e;
  }

  const configPersonas = (config && config.personas) || {};
  for (const key of Object.keys(configPersonas)) {
    if (!names.includes(key)) {
      console.error(`Warning: .righthand/persona.json configures unknown persona "${key}"`);
    }
  }

  const om = (function () {
    try {
      const pc = require('./persona-config');
      return pc.orchestratorModel();
    } catch (e) {
      return null;
    }
  })();

  if (personaArg) {
    if (!names.includes(personaArg)) {
      console.error(`Unknown persona: ${personaArg}`);
      console.error(`Available: ${names.join(', ')}`);
      process.exit(1);
    }
    try {
      console.log(formatResolution(cwd, personaArg, { orchestratorModel: om, config: config }));
    } catch (e) {
      if (e instanceof ConfigError) {
        console.error(`Error: ${e.message}`);
        process.exit(2);
      }
      throw e;
    }
    return;
  }

  for (const n of names) {
    try {
      console.log(formatResolution(cwd, n, { orchestratorModel: om, config: config }));
    } catch (e) {
      if (e instanceof ConfigError) {
        console.error(`Error: ${e.message}`);
        process.exit(2);
      }
      throw e;
    }
  }
}

function cmdLaunch(personaName, opts) {
  opts = opts || {};
  if (!personaName) {
    console.error(LAUNCH_USAGE);
    process.exit(1);
  }

  let explicitHarnessKey = null;
  let explicitHarnessName = null;
  if (opts.harness) {
    explicitHarnessKey = resolveHarness(opts.harness);
    if (!explicitHarnessKey) {
      console.error(`Unknown harness: ${opts.harness}`);
      console.error(`Available: ${Object.keys(HARNESSES).join(', ')}`);
      process.exit(1);
    }
    const explicitManifest = getHarnessManifest(explicitHarnessKey);
    explicitHarnessName = (explicitManifest && (explicitManifest.dispatchAlias || explicitManifest.key)) || explicitHarnessKey;
  }

  // --cwd validation
  let targetCwd = process.cwd();
  if (opts.cwd) {
    let st = null;
    try { st = fs.statSync(opts.cwd); } catch (e) { st = null; }
    if (!st || !st.isDirectory()) {
      console.error(`Error: --cwd does not exist or is not a directory: ${opts.cwd}`);
      process.exit(1);
    }
    targetCwd = opts.cwd;
  }

  const names = listProfiles();
  if (!names.includes(personaName)) {
    console.error(`Unknown persona: ${personaName}`);
    console.error(`Available: ${names.join(', ')}`);
    process.exit(1);
  }

  const cwd = process.cwd();
  let config;
  try {
    config = readConfig(cwd);
  } catch (e) {
    if (e instanceof ConfigError) {
      console.error(`Error: ${e.message}`);
      process.exit(2);
    }
    throw e;
  }

  const om = (function () {
    try {
      return require('./persona-config').orchestratorModel();
    } catch (e) {
      return null;
    }
  })();

  let resolution;
  try {
    // An explicit harness position pins the harness for this launch only; the
    // config file is left untouched. resolvePersona drops a model that belongs
    // to another harness and only forwards a per-harness `models` entry.
    resolution = resolvePersona(cwd, personaName, {
      orchestratorModel: om,
      config: config,
      targetHarness: explicitHarnessName,
    });
  } catch (e) {
    if (e instanceof ConfigError) {
      console.error(`Error: ${e.message}`);
      process.exit(2);
    }
    throw e;
  }

  if (!SUPPORTED_DISPATCH_HARNESSES.includes(resolution.harness)) {
    console.error(`Error: persona "${personaName}" uses harness "${resolution.harness}", not supported for dispatch; supported: ${SUPPORTED_DISPATCH_HARNESSES.join(', ')}`);
    process.exit(2);
  }

  const resolvedHarnessKey = resolveHarness(resolution.harness);
  const launchManifest = resolvedHarnessKey ? getHarnessManifest(resolvedHarnessKey) : null;
  if (!launchManifest || typeof launchManifest.buildLaunch !== 'function') {
    console.error(`Error: harness "${resolution.harness}" has no launch builder declared`);
    process.exit(2);
  }
  const launch = launchManifest.buildLaunch(personaName, resolution);
  const bin = launch.bin;
  const args = launch.args;
  const launchEnv = launch.env || {};

  if (opts.print) {
    console.log(formatCommand(bin, args));
    for (const [key, value] of Object.entries(launchEnv)) console.log(`env: ${key}=${value}`);
    process.exit(0);
  }

  const { spawn } = require('child_process');
  let child;
  try {
    child = spawn(bin, args, { cwd: targetCwd, stdio: 'inherit', shell: IS_WIN, env: Object.assign({}, process.env, launchEnv) });
  } catch (e) {
    console.error(`Error: unable to spawn ${bin}: ${e.message}`);
    process.exit(1);
  }
  child.on('error', (err) => {
    console.error(`Error: unable to spawn ${bin}: ${err.message}`);
    process.exit(1);
  });
  child.on('exit', (code) => {
    process.exit(code == null ? 1 : code);
  });
}

function cmdSetup(target, opts) {
  opts = opts || {};
  const dryRun = !!opts.dryRun;
  const targets = target === 'all'
    ? Object.keys(HARNESSES)
    : target ? [resolveHarness(target)].filter(Boolean) : null;

  if (!targets || targets.length === 0) {
    console.error(`Unknown harness: ${target}`);
    console.error(`Available: ${Object.keys(HARNESSES).join(', ')}, all`);
    process.exit(1);
  }

  for (const key of targets) {
    const h = HARNESSES[key];
    console.log(`\n[${h.label}]`);

    if (h.type === 'spawn') {
      if (!isInPath(h.bin)) {
        console.log(`  ✗ "${h.bin}" not found in PATH — install ${h.label} first`);
        continue;
      }
      if (dryRun) {
        console.log(`  → (dry run) ${h.bin} ${h.args.join(' ')}`);
      } else {
        console.log(`  → running: ${h.bin} ${h.args.join(' ')}`);
        const r = spawnSync(h.bin, h.args, { shell: true, stdio: 'inherit' });
        if (r.status === 0) {
          console.log(`  ✓ installed via ${h.bin}`);
        } else {
          console.log(`  ✗ install failed (exit ${r.status})`);
        }
      }
      runHarnessSkillsAndProfileCleanup(key, dryRun);
    } else if (h.type === 'copy') {
      for (const { src, dest } of h.files) {
        const srcPath = path.join(root, src);
        const destPath = resolveDestPath(h, dest);
        if (!fs.existsSync(srcPath)) {
          console.log(`  ✗ source not found: ${src}`);
          continue;
        }
        if (dryRun) {
          console.log(`  ✓ (dry run) ${destPath}`);
          continue;
        }
        fs.mkdirSync(path.dirname(destPath), { recursive: true });
        fs.copyFileSync(srcPath, destPath);
        console.log(`  ✓ copied → ${destPath}`);
      }
    }
  }
}

function cmdUpdate(target, opts) {
  opts = opts || {};
  const dryRun = !!opts.dryRun;
  const cwd = process.cwd();

  // Determine copy harness candidates
  const allCopy = Object.keys(HARNESSES).filter(k => HARNESSES[k].type === 'copy');
  const copyCandidates = target
    ? [resolveHarness(target)].filter(k => k && HARNESSES[k]?.type === 'copy')
    : allCopy;

  // spawn targets
  const spawnTargets = target
    ? [resolveHarness(target)].filter(k => k && HARNESSES[k]?.type === 'spawn')
    : [];

  // Check if any copy harness has existing destination files
  const existingCopy = copyCandidates.filter(key => {
    const h = HARNESSES[key];
    return h.files.some(({ dest }) => fs.existsSync(resolveDestPath(h, dest)));
  });

  if (copyCandidates.length > 0 && existingCopy.length === 0 && spawnTargets.length === 0) {
    console.log('No harness files found. Run: righthand setup <harness>');
    return;
  }

  if (existingCopy.length > 0) {
    console.log('Re-syncing harness files...');
    for (const key of existingCopy) {
      const h = HARNESSES[key];
      console.log(`\n[${h.label}]`);
      for (const { src, dest } of h.files) {
        const srcPath = path.join(root, src);
        const destPath = resolveDestPath(h, dest);
        if (!fs.existsSync(srcPath)) {
          console.log(`  ✗ source not found: ${src}`);
          continue;
        }
        if (!fs.existsSync(path.dirname(destPath))) {
          console.log(`  ✗ dest folder not found: ${path.dirname(destPath)} (run setup first?)`);
          continue;
        }
        if (!fs.existsSync(destPath)) {
          // only re-sync existing files
          continue;
        }
        if (dryRun) {
          console.log(`  ✓ (dry run) ${destPath}`);
          continue;
        }
        fs.copyFileSync(srcPath, destPath);
        console.log(`  ✓ updated → ${destPath}`);
      }
    }
  }

  // Spawn harnesses auto-update via package manager
  if (spawnTargets.length > 0) {
    for (const key of spawnTargets) {
      const h = HARNESSES[key];
      console.log(`\n[${h.label}] — updating via package manager`);
      if (!isInPath(h.bin)) {
        console.log(`  ✗ "${h.bin}" not found in PATH`);
        continue;
      }
      if (!dryRun) {
        const r = spawnSync(h.bin, h.args, { shell: true, stdio: 'inherit' });
        if (r.status === 0) {
          console.log(`  ✓ updated`);
        } else {
          console.log(`  ✗ update failed (exit ${r.status})`);
        }
      } else {
        console.log(`  → (dry run) ${h.bin} ${h.args.join(' ')}`);
      }
      runHarnessSkillsAndProfileCleanup(key, dryRun);
    }
  }

  if (existingCopy.length === 0 && spawnTargets.length === 0) {
    // maybe target copy with no existing files
    if (copyCandidates.length > 0) {
      console.log('No harness files found. Run: righthand setup <harness>');
    } else {
      console.log('Nothing to update. For Pi/CommandCode, use their own package manager.');
    }
  }
}

function cmdDoctor() {
  const cwd = process.cwd();
  const strict = process.argv.includes('--strict');

  console.log(`RightHand Doctor v${pkg.version}`);
  console.log('\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n');

  // Package health
  const profileCount = listProfiles().length;
  const skillCount = fs.existsSync(skillsDir) ? fs.readdirSync(skillsDir).filter(f => !f.startsWith('.')).length : 0;
  const skillStatus = checkSkills();
  console.log('Package:');
  console.log(`  ✓ righthand  v${pkg.version}`);
  console.log(`  ${profileCount > 0 ? '✓' : '✗'} profiles   ${profileCount} personas`);
  console.log(`  ${skillCount > 0 ? '✓' : '✗'} skills     ${skillCount} skills`);
  const skillOk = skillStatus.total > 0 && skillStatus.installed === skillStatus.total;
  console.log(`  ${skillOk ? '✓' : '✗'} skills installed: ${skillStatus.installed}/${skillStatus.total}`);
  if (skillStatus.missingOrStale.length > 0) {
    console.log(`             missing/stale: ${skillStatus.missingOrStale.join(', ')}`);
  }

  // Persona config + mod health
  console.log('\nPersona config & mod:');
  const pcResult = dc.checkPersonaConfig(cwd);
  if (pcResult.status === 'missing') {
    console.log('  - persona config: none');
  } else if (pcResult.status === 'error') {
    console.log(`  ✗ persona config: ${pcResult.path} ${pcResult.message}`);
  } else {
    console.log(`  ✓ persona config: ${pcResult.path} (${pcResult.entries} entries)`);
  }
  for (const name of pcResult.unknownPersonas) {
    console.log(`  - unknown persona: ${name}`);
  }
  for (const h of pcResult.unsupportedHarnesses) {
    console.log(`  - unsupported harness: ${h.persona} ${h.harness}`);
  }

  const ctx = harnessContext();
  for (const m of registry.listManifests()) {
    if (typeof m.doctorModLines !== 'function') continue;
    for (const line of m.doctorModLines(ctx)) console.log(line);
  }

  // Harness PATH check
  console.log('\nHarness PATH:');
  for (const [key, h] of Object.entries(HARNESSES)) {
    const m = getHarnessManifest(key);
    if (h.pathCheck && h.pathCheck.length > 0) {
      const found = h.pathCheck.some(b => isInPath(b));
      const displayBin = h.pathCheck.join(' / ');
      const extra = m && typeof m.pathNote === 'string' ? m.pathNote : '';
      console.log(`  ${found ? '✓' : '✗'} ${displayBin.padEnd(12)} ${found ? 'found' : 'not in PATH'}${extra}`);
    } else {
      console.log(`  - ${key.padEnd(12)} auto-discovered (no binary)`);
    }
  }

  // Setup status
  console.log('\nSetup Status (this project):');
  console.log(`  righthand initialized: ${fs.existsSync(path.join(cwd, '.righthand', 'tickets')) ? 'yes' : 'no'}`);

  let anySetup = false;

  for (const [key, h] of Object.entries(HARNESSES)) {
    const m = getHarnessManifest(key);
    if (m && typeof m.doctorSetupLines === 'function') {
      const res = m.doctorSetupLines(ctx);
      for (const line of res.lines) console.log(line);
      if (res.anySetup) anySetup = true;
      continue;
    }
    if (h.type === 'copy') {
      const allExist = h.files.every(({ dest }) => fs.existsSync(resolveDestPath(h, dest)));
      const status = allExist ? '✓' : '✗';
      if (allExist) anySetup = true;
      console.log(`  ${status} ${key.padEnd(10)} ${allExist ? 'files present' : 'not set up'}`);
      for (const { dest } of h.files) {
        const destPath = resolveDestPath(h, dest);
        const exists = fs.existsSync(destPath);
        console.log(`             ${exists ? '✓' : '✗'} ${destPath}`);
      }
      if (!allExist) {
        console.log(`             Run: righthand setup ${key}`);
      }
      if (h.legacyFiles) {
        const stale = h.legacyFiles
          .map(p => path.isAbsolute(p) ? p : path.join(os.homedir(), p))
          .filter(p => fs.existsSync(p));
        if (stale.length > 0) {
          console.log(`             ⚠ legacy stale install found (remove manually):`);
          for (const p of stale) console.log(`               ${p}`);
        }
      }
    } else if (h.type === 'spawn') {
      const found = h.pathCheck && h.pathCheck.length > 0 ? h.pathCheck.some(b => isInPath(b)) : false;
      console.log(`  ${found ? '✓' : '✗'} ${key.padEnd(10)} ${found ? 'available' : 'not in PATH'}`);
      if (typeof m.contributesAnySetup === 'function') {
        if (m.contributesAnySetup(ctx)) anySetup = true;
      }
    }
  }
  console.log(`  ${anySetup ? '✓' : '-'} any harness setup: ${anySetup ? 'detected' : 'none detected'}`);

  // Active persona
  const state = readState(cwd);
  console.log(`\nActive Persona: ${state.active ? `${state.active}` : 'none'}`);

  // Legacy user profiles (informational only)
  const legacyOwner = firstManifestWithHook('userProfilesDir');
  if (legacyOwner) {
    const legacyUserDir = legacyOwner.userProfilesDir();
    if (fs.existsSync(legacyUserDir)) {
      let legacyFiles = [];
      try {
        legacyFiles = fs.readdirSync(legacyUserDir).filter((f) => f.endsWith('.md') && !f.startsWith('.'));
      } catch (e) {
        legacyFiles = [];
      }
      const legacyNames = legacyFiles.map((f) => f.slice(0, -3));
      const retiredFound = legacyNames.filter((n) => RETIRED_PERSONAS.indexOf(n) !== -1);
      const shippedSet = new Set(listProfiles());
      const shadowing = legacyNames.filter((n) => shippedSet.has(n));
      console.log(`\nLegacy user profiles (${legacyUserDir}): ${legacyFiles.length} files`);
      if (retiredFound.length > 0) console.log(`  retired: ${retiredFound.join(', ')}`);
      if (shadowing.length > 0) console.log(`  shadow shipped: ${shadowing.join(', ')}`);
    }
  }

  const strictFailures = dc.collectStrictFailures({
    personaConfig: pcResult,
    skills: skillStatus,
    harnesses: collectStrictHarnessData(ctx)
  });
  if (strict && strictFailures.length > 0) process.exit(1);
  if (strict) process.exit(0);
}

// ---------------------------------------------------------------------------
// CLI routing
// ---------------------------------------------------------------------------
const argv = process.argv.slice(2);
const cmd = argv[0];
const dryRun = argv.includes('--dry-run');
const positional = argv.filter((a) => !a.startsWith('--'));
const arg = positional[1];

if (!cmd || cmd === 'list') {
  cmdList();
} else if (cmd === 'switch') {
  cmdSwitch(arg);
} else if (cmd === 'off') {
  cmdOff();
} else if (cmd === 'inject') {
  cmdInject();
} else if (cmd === 'status') {
  cmdStatus();
} else if (cmd === 'init') {
  cmdInit();
} else if (cmd === 'setup') {
  cmdSetup(positional[1] || 'all', { dryRun });
} else if (cmd === 'update') {
  cmdUpdate(positional[1], { dryRun });
} else if (cmd === 'doctor') {
  cmdDoctor();
} else if (cmd === 'config') {
  cmdConfig(arg);
} else if (cmd === 'launch') {
  const rest = argv.slice(1);
  const launchPositional = [];
  let cwdOpt = null;
  let print = false;
  for (let i = 0; i < rest.length; i++) {
    const a = rest[i];
    if (a === '--print') {
      print = true;
    } else if (a === '--cwd') {
      if (i + 1 >= rest.length) {
        console.error('Error: missing argument for --cwd');
        process.exit(1);
      }
      cwdOpt = rest[++i];
    } else if (!a.startsWith('--')) {
      launchPositional.push(a);
    }
  }
  if (launchPositional.length > 2) {
    console.error(LAUNCH_USAGE);
    process.exit(1);
  }
  const launchHarness = launchPositional.length === 2 ? launchPositional[0] : null;
  const personaName = launchPositional.length === 2 ? launchPositional[1] : launchPositional[0];
  cmdLaunch(personaName, { cwd: cwdOpt, print, harness: launchHarness });
} else if (cmd === '-v' || cmd === '--version' || cmd === 'version') {
  cmdVersion();
} else if (cmd === '-h' || cmd === '--help' || cmd === 'help') {
  cmdHelp();
} else {
  console.error(`Unknown command: ${cmd}`);
  console.error('Run: righthand --help');
  process.exit(1);
}

const fs = require('fs');
const path = require('path');

function getStateDir(cwd = process.cwd()) {
  return path.join(cwd, '.righthand', 'state');
}

function getStateFile(cwd = process.cwd()) {
  return path.join(getStateDir(cwd), 'active-persona.json');
}

function getLegacyStateFile(cwd = process.cwd()) {
  return path.join(cwd, '.righthand', 'active-persona.json');
}

function readState(cwd = process.cwd()) {
  try {
    const p = getStateFile(cwd);
    if (!fs.existsSync(p)) {
      // Fallback to legacy path for projects created by older versions.
      const legacy = getLegacyStateFile(cwd);
      if (fs.existsSync(legacy)) {
        const raw = fs.readFileSync(legacy, 'utf8');
        return JSON.parse(raw);
      }
      return { active: null };
    }
    const raw = fs.readFileSync(p, 'utf8');
    return JSON.parse(raw);
  } catch {
    return { active: null };
  }
}

function writeState(state, cwd = process.cwd()) {
  const dir = getStateDir(cwd);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const target = getStateFile(cwd);
  const tmp = path.join(dir, `.active-persona.${process.pid}.tmp`);
  fs.writeFileSync(tmp, JSON.stringify(state, null, 2) + '\n');
  fs.renameSync(tmp, target);
}

module.exports = { getStateDir, getStateFile, readState, writeState, getLegacyStateFile };

